/** 仅编译本轮合成费用作品的完整实现和独立测试类，不运行模型测试，也不继承模型密钥。 */
import { readFile, readdir, writeFile, mkdir } from 'node:fs/promises';
import { resolve, join, sep } from 'node:path';
import { createHash } from 'node:crypto';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const execute = promisify(execFile), hash = value => createHash('sha256').update(value).digest('hex');
const [source, target] = process.argv.slice(2);
const checkLabel = process.argv[4] ?? 'reviewed';
if (!/^[a-z0-9-]{1,40}$/.test(checkLabel)) throw new Error('INVALID_CHECK_LABEL');
const run = resolve(source), output = resolve(target);
if (!run.startsWith(resolve('tmp/prompt-output-evaluation') + sep) || !output.startsWith(resolve('tmp') + sep)) throw new Error('OWNED_TMP_REQUIRED');
const text = await readFile(join(run, 'jobs.json'), 'utf8');
const manifest = JSON.parse(await readFile(join(run, 'manifest.json'), 'utf8'));
if (hash(text) !== manifest.jobsSha256) throw new Error('FROZEN_JOBS_CHANGED');
const env = Object.fromEntries(['PATH', 'SystemRoot', 'WINDIR', 'TEMP', 'TMP', 'JAVA_HOME'].filter(name => process.env[name]).map(name => [name, process.env[name]]));
const javac = env.JAVA_HOME ? join(env.JAVA_HOME, 'bin/javac.exe') : 'javac';
const repository = 'E:/Delelop/localRepository';
const junitJars = [];
for (const module of ['org/junit/jupiter/junit-jupiter-api', 'org/junit/platform/junit-platform-commons', 'org/apiguardian/apiguardian-api', 'org/opentest4j/opentest4j']) {
  const directory = join(repository, module);
  try {
    const versions = (await readdir(directory, { withFileTypes: true })).filter(entry => entry.isDirectory() && /^[0-9.]+$/.test(entry.name)).map(entry => entry.name).sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));
    const version = versions.at(-1);
    if (version) for (const name of await readdir(join(directory, version))) if (/\.jar$/.test(name) && !/(?:sources|javadoc)/.test(name)) junitJars.push(join(directory, version, name));
  } catch { /* 仅缺少可选本地测试库时标记未验证，不伪造编译通过。 */ }
}
const base = resolve('tmp/java-test-delivery-check', run.split(/[\\/]/).at(-1) + '-' + checkLabel);
await mkdir(base, { recursive: true });
const entries = [];
for (const job of JSON.parse(text).jobs.filter(job => job.caseId === 'RC-DEV-M')) {
  const actual = JSON.parse(await readFile(join(run, 'execution', job.id + '.json'), 'utf8'));
  const record = { id: job.id, arm: job.arm, modelId: job.modelId, outputSha256: actual.outputSha256 };
  if (actual.status !== 'SUCCESS') { entries.push({ ...record, status: actual.status }); continue; }
  if (hash(actual.output) !== actual.outputSha256 || actual.executionUserSha256 !== job.userHash) throw new Error('ACTUAL_WORK_CHANGED');
  const blocks = [...actual.output.matchAll(/```(?:java)?\s*\r?\n([\s\S]*?)\r?\n```/g)].map(match => match[1]);
  const implementations = blocks.filter(code => /public\s+final\s+class\s+FeeCalculator\b/.test(code));
  const tests = blocks.filter(code => /public\s+(?:final\s+)?class\s+(?!FeeCalculator\b)([a-zA-Z_][a-zA-Z0-9_]*(?:Test|Tests))\b/.test(code));
  if (implementations.length !== 1 || tests.length !== 1) { entries.push({ ...record, status: 'FULL_TEST_CLASS_NEEDS_REVIEW', implementationBlocks: implementations.length, testBlocks: tests.length }); continue; }
  const implementation = implementations[0], test = tests[0];
  const testName = /public\s+(?:final\s+)?class\s+([a-zA-Z_][a-zA-Z0-9_]*)/.exec(test)?.[1];
  const imports = [...(implementation + '\n' + test).matchAll(/\bimport\s+(?:static\s+)?([^;]+);/g)].map(match => match[1].trim());
  // Class<T>仅为断言的类型参数，不是动态加载；仍拦截加载、进程、网络和文件入口，不执行测试代码。
  if (implementation.length + test.length > 40000 || /\b(?:Runtime|ProcessBuilder|Thread|ClassLoader|Files|Path|File|Socket|ServerSocket|URL|Unsafe|native)\b|\bClass\s*\.|\\u[0-9a-fA-F]{4}|\bpackage\s/.test(implementation + '\n' + test)
      || imports.some(name => !/^java\.(?:math|util)\.[a-zA-Z0-9_.*]+$|^org\.junit\.jupiter\.api\.[a-zA-Z0-9_.*]+$/.test(name))) { entries.push({ ...record, status: 'NOT_COMPILED_UNSUPPORTED_ENTRY' }); continue; }
  if (/org\.junit/.test(test) && junitJars.length === 0) { entries.push({ ...record, status: 'MISSING_OPTIONAL_TEST_DEPENDENCY' }); continue; }
  const dir = join(base, job.id);
  await mkdir(dir);
  await writeFile(join(dir, 'FeeCalculator.java'), implementation, { flag: 'wx' });
  await writeFile(join(dir, testName + '.java'), test, { flag: 'wx' });
  try {
    await execute(javac, ['-J-Xmx128m', '-J-Duser.language=en', '-J-Duser.country=US', '-proc:none', '-encoding', 'UTF-8', '--release', '21', '-cp', ['.', ...junitJars].join(';'), 'FeeCalculator.java', testName + '.java'], { cwd: dir, env, timeout: 20000, windowsHide: true, maxBuffer: 65536 });
    entries.push({ ...record, status: 'COMPILED', testClass: testName, generatedTestsExecuted: false });
  } catch (error) { entries.push({ ...record, status: 'COMPILE_FAILED', error: String(error.stderr ?? error.message).slice(0, 1200) }); }
}
await writeFile(output, JSON.stringify({ sourceRun: run, scope: 'SYNTHETIC_FEE_IMPLEMENTATION_AND_TEST_COMPILATION_ONLY', entries }, null, 2) + '\n', { flag: 'wx' });
console.log(JSON.stringify({ records: entries.length, compiled: entries.filter(entry => entry.status === 'COMPILED').length, other: entries.filter(entry => entry.status !== 'COMPILED').map(entry => ({ id: entry.id, status: entry.status })) }));
